 struct V {public Vector3 p,n;public Vector4 t;public Vector2 uv,uv2;public Color color; public static V Lerp(V a,V b,float x){return new V{p=Vector3.Lerp(a.p,b.p,x),n=Vector3.Lerp(a.n,b.n,x).normalized,t=Vector4.Lerp(a.t,b.t,x),uv=Vector2.Lerp(a.uv,b.uv,x),uv2=Vector2.Lerp(a.uv2,b.uv2,x),color=Color.Lerp(a.color,b.color,x)};}}
 static List<V> Clip(List<V> p,int axis,float limit,bool lower){var r=new List<V>();for(int i=0;i<p.Count;i++){var a=p[i];var b=p[(i+1)%p.Count];float av=a.p[axis]-limit,bv=b.p[axis]-limit;bool ai=lower?av<=0:av>=0,bi=lower?bv<=0:bv>=0;if(ai)r.Add(a);if(ai!=bi)r.Add(V.Lerp(a,b,av/(av-bv)));}return r;}
 static List<List<V>> SubtractDoor(List<V> p){var keep=new List<List<V>>();int[] axes={0,0,1,1};float[] limits={-.36f,.36f,.70f,1.974f};bool[] lower={true,false,true,false};for(int i=0;i<4&&p.Count>=3;i++){var outside=Clip(p,axes[i],limits[i],lower[i]);if(outside.Count>=3)keep.Add(outside);p=Clip(p,axes[i],limits[i],!lower[i]);}return keep;}
