 static int SplitDoor(GameObject root,Transform pivot,List<string> report){int total=0;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>new[]{"camper_body","camper_interior","windows"}.Contains(f.name)).ToArray()){
